///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_sendSucEndForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_sendSucEndForm = async function () {
    const sbmOptions = {
        id: "tx_sendSucEndForm",
        method: "post",
        action: "/account/disclsUserInfo.do?method=disclsUserInfo",
        ref: "dma_sendSucEndFormReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldods10041.tx_sendSucEndForm" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

